import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createServer, request as httpRequest } from 'node:http';
import { ROLE_DEFINITIONS, ROLE_KEYS } from '../src/roles.js';
import { SIDEBAR_CATEGORIES, visibleSidebar } from '../src/sidebar-registry.js';
import { ADMISSION_STAGES, CORE_LEVELS, createStudentService } from '../src/students.js';
import { createAuditLog } from '../src/audit.js';
import { createAuthService } from '../src/auth.js';
import { createApp } from '../src/server.js';
import '../src/module-registry.js';
import { ATTENDANCE_METHODS, STUDENT_STATUSES, createAttendanceService } from '../src/attendance.js';
import { DEFAULT_GRADING, PROMOTION_DECISIONS, RESULT_STATES, createExaminationService } from '../src/examinations.js';

test('role definitions include all required roles and proprietor is highest', () => { assert.equal(ROLE_DEFINITIONS.length, 21); assert.equal(ROLE_DEFINITIONS.find((r) => r.roleKey === 'PROPRIETOR').oversightRank, 100); assert.ok(ROLE_KEYS.has('PARENT')); assert.ok(ROLE_KEYS.has('STUDENT')); });
test('sidebar registry filters by permission and sorts modules', () => { const groups = visibleSidebar({ permissions: new Set(['users.read']) }); assert.equal(groups.length, 2); const system = groups.find((group) => group.category === 'SYSTEM & SECURITY'); assert.equal(system.modules[0].moduleKey, 'users'); assert.equal(SIDEBAR_CATEGORIES.length, 20); });
test('sidebar registry accepts a future module without editing navigation code', () => { const groups = visibleSidebar({ modules: [{ moduleKey: 'fees', moduleName: 'Fees', category: 'FEE HUB', route: '/fees', icon: '$', displayOrder: 1, requiredPermission: null, enabled: true }], permissions: new Set() }); assert.equal(groups[0].modules[0].moduleKey, 'fees'); });
test('audit logs require action and entity and are immutable-style', () => { const log = createAuditLog({ action: 'UPDATE', entity: 'School', entityId: 'school-1', previousValue: { name: 'Old' }, newValue: { name: 'New' } }, () => '2026-09-02T00:00:00.000Z'); assert.equal(log.occurredAt, '2026-09-02T00:00:00.000Z'); assert.throws(() => { log.action = 'DELETE'; }, TypeError); assert.throws(() => createAuditLog({ action: 'READ' }), /entity/); });
test('foundation schema contains relational anchors and audit indexes', async () => { const schema = await readFile(new URL('../schema/001_foundation.sql', import.meta.url), 'utf8'); const studentSchema = await readFile(new URL('../schema/003_students_admissions.sql', import.meta.url), 'utf8'); for (const table of ['schools', 'academic_years', 'terms', 'levels', 'classes', 'streams', 'subjects', 'departments', 'houses', 'users', 'roles', 'permissions', 'user_roles', 'sidebar_modules', 'sidebar_categories', 'system_settings', 'audit_logs', 'students', 'staff']) assert.match(schema, new RegExp(`CREATE TABLE IF NOT EXISTS ${table}`)); for (const table of ['student_profiles', 'student_family_contacts', 'student_health_records', 'student_documents', 'student_class_history', 'parent_student_links', 'admission_applications']) assert.match(studentSchema, new RegExp(`CREATE TABLE IF NOT EXISTS ${table}`)); assert.match(schema, /REFERENCES schools\(id\)/); assert.match(schema, /idx_audit_entity/); });
test('foundation seed preserves official school identity and registry categories', async () => { const seed = await readFile(new URL('../schema/002_foundation_seed.sql', import.meta.url), 'utf8'); assert.match(seed, /OSAAH DAYLIGHT SCH\. COM\./); assert.match(seed, /AIM HIGH, ACADEMIC IS OUR CORE VALUE/); assert.match(seed, /school-osaah-daylight/); assert.equal((seed.match(/UNION ALL SELECT/g) ?? []).length, 19); });
test('mobile-first shell includes exactly two portal cards', async () => { const html = await readFile(new URL('../public/index.html', import.meta.url), 'utf8'); const css = await readFile(new URL('../public/styles.css', import.meta.url), 'utf8'); assert.equal((html.match(/class="portal-card"/g) ?? []).length, 2); assert.match(html, /PARENT PORTAL/); assert.match(html, /SCHOOL PORTAL/); assert.match(html, /name="viewport"/); assert.match(css, /min-width:320px/); assert.match(css, /@media\(min-width:760px\)/); assert.match(css, /\.sidebar\{/); });
test('official logo asset is present and referenced without replacement', async () => { const logo = await readFile(new URL('../public/assets/osaah-daylight-logo.png', import.meta.url)); const html = await readFile(new URL('../public/index.html', import.meta.url), 'utf8'); assert.equal(logo[0], 0x89); assert.equal(logo[1], 0x50); assert.match(html, /assets\/osaah-daylight-logo\.png/); });
test('parent and school logins are separated by portal and expose authorized children', () => { const auth = createAuthService(); const parent = auth.login({ username: 'parent@example.com', password: 'Parent123!', portal: 'parent' }); const school = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); assert.equal(parent.ok, true); assert.equal(parent.user.roleKey, 'PARENT'); assert.equal(school.ok, true); assert.equal(school.user.roleKey, 'TEACHER'); assert.equal(auth.login({ username: 'parent@example.com', password: 'Parent123!', portal: 'school' }).ok, false); assert.equal(auth.authenticate(parent.token).children.length, 1); });
test('sessions expire and failed login protection activates', () => { let clock = 1000; const auth = createAuthService({ now: () => clock }); for (let i = 0; i < 5; i += 1) auth.login({ username: 'teacher@osaah.edu.gh', password: 'wrong', portal: 'school' }); assert.equal(auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }).status, 429); const valid = auth.login({ username: 'proprietor@osaah.edu.gh', password: 'Proprietor123!', portal: 'school' }); clock += 1_800_001; assert.equal(auth.authenticate(valid.token), null); });
test('password reset tokens are single-use and invalidate existing sessions', () => { const auth = createAuthService(); const session = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const reset = auth.requestPasswordReset('teacher@osaah.edu.gh'); assert.equal(auth.completePasswordReset(reset.token, 'NewTeacher123!').ok, true); assert.equal(auth.authenticate(session.token), null); assert.equal(auth.login({ username: 'teacher@osaah.edu.gh', password: 'NewTeacher123!', portal: 'school' }).ok, true); assert.equal(auth.completePasswordReset(reset.token, 'Another123!').ok, false); });
test('protected API rejects anonymous users and enforces role restrictions', async () => { const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (path, options = {}) => new Promise((resolve, reject) => { const req = httpRequest({ port, path, method: options.method ?? 'GET', headers: options.headers ?? {} }, (res) => { let body = ''; res.on('data', (chunk) => { body += chunk; }); res.on('end', () => resolve({ status: res.statusCode, body, headers: res.headers })); }); req.on('error', reject); if (options.body) req.write(options.body); req.end(); }); const anonymous = await request('/api/management'); assert.equal(anonymous.status, 401); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const forbidden = await request('/api/management', { headers: { Authorization: `Bearer ${teacher.token}` } }); assert.equal(forbidden.status, 403); const proprietor = auth.login({ username: 'proprietor@osaah.edu.gh', password: 'Proprietor123!', portal: 'school' }); const allowed = await request('/api/management', { headers: { Authorization: `Bearer ${proprietor.token}` } }); assert.equal(allowed.status, 200); await new Promise((resolve) => server.close(resolve)); });
test('specialist roles receive only their registered modules', () => { const cases = [['ACCOUNTANT_BURSAR', ['fees', 'finance']], ['LIBRARIAN', ['library']], ['TRANSPORT_MANAGER', ['transport']]]; for (const [roleKey, moduleKeys] of cases) { const groups = visibleSidebar({ permissions: new Set(['fees.read', 'finance.read', 'library.read', 'transport.read']), roleKey }); const keys = groups.flatMap((group) => group.modules.map((module) => module.moduleKey)); assert.deepEqual(keys, moduleKeys); } });
test('student creation generates a permanent unique ID and rejects duplicate admission numbers', () => { const service = createStudentService({ now: () => '2026-09-02T00:00:00.000Z' }); const first = service.createStudent({ admissionNumber: 'ADM-001', firstName: 'Ama', surname: 'Mensah', classId: 'primary-4' }); const second = service.createStudent({ admissionNumber: 'ADM-002', firstName: 'Kojo', surname: 'Mensah' }); assert.equal(first.id, 'STD-000001'); assert.equal(second.id, 'STD-000002'); assert.equal(first.qrCode, 'osaah:student:STD-000001'); assert.equal(first.history.length, 1); assert.throws(() => service.createStudent({ admissionNumber: 'ADM-001', firstName: 'Duplicate', surname: 'Student' }), /already exists/); });
test('student history preserves identity across class assignment and links multiple parents', () => { const service = createStudentService(); const student = service.createStudent({ firstName: 'Esi', surname: 'Owusu' }); service.assignClass(student.id, { classId: 'primary-5', academicYearId: '2026' }); service.assignClass(student.id, { classId: 'jhs-1', academicYearId: '2027', reason: 'PROMOTION' }); service.linkParent(student.id, { parentId: 'parent-1', relationship: 'Mother', telephone: '0240000000' }); const links = service.linkParent(student.id, { parentId: 'parent-2', relationship: 'Father' }); const record = service.getStudent(student.id); assert.equal(record.id, student.id); assert.equal(record.history.length, 2); assert.equal(links.length, 2); });
test('student search supports parent phone and assigned-student RBAC', () => { const service = createStudentService(); const assigned = service.createStudent({ firstName: 'Yaw', surname: 'Boateng', family: [{ telephone: '0241111111' }] }); service.createStudent({ firstName: 'Akua', surname: 'Darko', family: [{ telephone: '0242222222' }] }); assert.equal(service.search('0241111111', { roleKey: 'TEACHER', assignedStudentIds: [assigned.id] }).length, 1); assert.equal(service.search('0242222222', { roleKey: 'TEACHER', assignedStudentIds: [assigned.id] }).length, 0); });
test('admissions workflow enforces order and generates offer and enrollment documents', () => { const service = createStudentService(); const application = service.createAdmission({ applicantName: 'Adwoa' }); let current = application; for (const stage of ADMISSION_STAGES.slice(1)) current = service.advanceAdmission(application.applicationNumber, stage); assert.equal(current.stage, 'CLASS_ASSIGNMENT'); assert.equal(current.admissionLetter, `ADMISSION-OFFER-${application.applicationNumber}`); assert.equal(current.enrollmentConfirmation, `ENROLLMENT-${application.applicationNumber}`); assert.throws(() => service.advanceAdmission(application.applicationNumber, 'ENROLLMENT'), /Invalid admission transition/); });
test('student levels cover the required structure and sidebar modules register automatically', () => { assert.deepEqual(CORE_LEVELS.slice(0, 2), ['KG1', 'KG2']); assert.equal(CORE_LEVELS.at(-1), 'JHS 3'); const studentGroup = visibleSidebar({ permissions: new Set(['students.read']), roleKey: 'TEACHER' }).find((group) => group.category === 'STUDENTS MANAGEMENT'); const admissionsGroup = visibleSidebar({ permissions: new Set(['admissions.read']), roleKey: 'ADMISSIONS_OFFICER' }).find((group) => group.category === 'ADMISSIONS'); assert.equal(studentGroup.modules[0].moduleKey, 'student-profiles'); assert.equal(admissionsGroup.modules[0].moduleKey, 'admissions'); });
test('attendance records support statuses, methods, summaries, and duplicate protection', () => { const service = createAttendanceService(); const actor = { userId: 'teacher-1' }; assert.ok(STUDENT_STATUSES.includes('LATE')); assert.ok(ATTENDANCE_METHODS.includes('QR_CODE')); service.saveStudentAttendance({ date: '2026-09-02', classId: 'primary-4', studentId: 'student-1', status: 'PRESENT', method: 'QR_CODE' }, actor); service.saveStudentAttendance({ date: '2026-09-02', classId: 'primary-4', studentId: 'student-2', status: 'LATE' }, actor); assert.equal(service.summary({ date: '2026-09-02', classId: 'primary-4' }).attendancePercentage, 100); assert.throws(() => service.saveStudentAttendance({ date: '2026-09-02', classId: 'primary-4', studentId: 'student-1', status: 'ABSENT' }, actor), /already recorded/); });
test('attendance corrections and offline sync reject stale overwrites', () => { const service = createAttendanceService(); const actor = { userId: 'teacher-1' }; const entry = { date: '2026-09-02', studentId: 'student-1', status: 'PRESENT' }; const current = service.saveStudentAttendance(entry, actor); service.saveStudentAttendance({ ...entry, status: 'LATE' }, actor, { correction: true, expectedVersion: current.version }); assert.throws(() => service.saveStudentAttendance({ ...entry, status: 'ABSENT' }, actor, { correction: false, expectedVersion: 1 }), /already recorded/); assert.throws(() => service.saveStudentAttendance({ ...entry, status: 'ABSENT' }, actor, { correction: true, expectedVersion: 1 }), /newer/); });
test('examinations calculate weighted marks and configurable grades', () => { const service = createExaminationService(); assert.equal(service.calculateMarks(85, 50).weightedMarks, 42.5); assert.equal(service.calculateMarks(85, 100).grade, 'A'); service.setGradingSystem('custom', [{ min: 90, grade: 'Distinction', remark: 'Outstanding' }, { min: 0, grade: 'Pass', remark: 'Pass' }]); assert.equal(service.calculateMarks(92, 100, 'custom').grade, 'Distinction'); assert.equal(DEFAULT_GRADING.length, 5); });
test('examination result publication is ordered and corrections are authorized', () => { const service = createExaminationService(); const exam = service.createExamination({ name: 'End of Term', type: 'END_OF_TERM' }); const actor = { userId: 'teacher', canApprove: true, canCorrect: true }; const mark = service.enterMarks({ examId: exam.id, studentId: 'student-1', subjectId: 'math', rawMarks: 75 }, actor); for (const state of RESULT_STATES.slice(1)) service.transitionResult(exam.id, 'student-1', 'math', state, actor); assert.throws(() => service.enterMarks({ examId: exam.id, studentId: 'student-1', subjectId: 'math', rawMarks: 60 }, { userId: 'teacher' }), /locked/); const corrected = service.enterMarks({ examId: exam.id, studentId: 'student-1', subjectId: 'math', rawMarks: 60 }, actor, { correction: true }); assert.equal(corrected.state, 'DRAFT'); assert.ok(mark.id); });
test('promotion decisions preserve history and support all outcomes', () => { const service = createExaminationService(); const record = service.promote('student-1', '2026', 'PROMOTED', { userId: 'headteacher' }, 'Ready for next level'); assert.ok(PROMOTION_DECISIONS.includes(record.decision)); assert.equal(record.studentId, 'student-1'); });
test('examination modules register under the results category and mobile score entry is responsive', async () => { const group = visibleSidebar({ permissions: new Set(['examinations.read', 'marks.write', 'results.read', 'promotion.write']), roleKey: 'PROPRIETOR' }).find((item) => item.category === 'EXAMINATIONS & RESULTS'); assert.deepEqual(group.modules.map((module) => module.moduleKey), ['examinations', 'marks-entry', 'results', 'promotion']); const html = await readFile(new URL('../public/examinations.html', import.meta.url), 'utf8'); const css = await readFile(new URL('../public/styles.css', import.meta.url), 'utf8'); assert.match(html, /score-grid/); assert.match(css, /\.score-grid\{/); });
